import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"API Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/api-analyzer.md","filePath":"new-features/api-analyzer.md"}'),s={name:"new-features/api-analyzer.md"};function n(o,e,d,l,h,p){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="api-analyzer" tabindex="-1">API Analyzer <a class="header-anchor" href="#api-analyzer" aria-label="Permalink to &quot;API Analyzer&quot;">​</a></h1><h3 id="what-analyzer-mode-does" tabindex="-1">What Analyzer Mode Does <a class="header-anchor" href="#what-analyzer-mode-does" aria-label="Permalink to &quot;What Analyzer Mode Does&quot;">​</a></h3><p>Analyzer Mode routes supported trading and account operations to Tradeboard&#39;s sandbox instead of the live broker. Simulated orders, trades, positions, holdings, funds, and configuration are stored in the separate <code>sandbox.db</code> store.</p><p>Market prices still come from the active broker data services. A broker connection and the relevant market-data entitlement may therefore be required. Analyzer Mode is an execution sandbox, not an exchange emulator or portfolio backtesting engine.</p><h3 id="enable-and-verify" tabindex="-1">Enable and Verify <a class="header-anchor" href="#enable-and-verify" aria-label="Permalink to &quot;Enable and Verify&quot;">​</a></h3><p>Use the mode control in Tradeboard, or call:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/analyzer</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/analyzer/toggle</span></span></code></pre></div><p>Enable with:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apikey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;your_app_apikey&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The setting is application-wide for the single-user deployment, not per API key. The toggle API is blocked in semi-auto mode; in that posture the client must change mode from the authenticated UI.</p><p>Always verify the current mode before an automated run. Turning Analyzer Mode off returns supported order flows to live broker execution.</p><h3 id="supported-behavior" tabindex="-1">Supported Behavior <a class="header-anchor" href="#supported-behavior" aria-label="Permalink to &quot;Supported Behavior&quot;">​</a></h3><ul><li>Regular, smart, basket, split, options, and multi-options services use sandbox paths where implemented.</li><li>MARKET orders can complete from current prices; LIMIT, SL, and SL-M orders can remain pending until their conditions are met.</li><li>The execution engine uses WebSocket prices when available and can fall back to polling.</li><li>Position book, holdings, funds, order book, trade book, status, modify, cancel, close, and P&amp;L services use sandbox state where their analyzer branches exist.</li><li>GTT is fully simulated. Place, modify, cancel, and the GTT order book all route to a sandbox GTT engine that holds single-leg and two-leg OCO triggers, blocks margin at placement, and fires a real sandbox order when a leg&#39;s trigger price is crossed. HTTP 501 now only appears in live mode, when the active broker ships no GTT module.</li><li>Expired F&amp;O contracts are settled inside the sandbox. <code>expiry_settlement_timing</code> chooses between exchange close on expiry day and midnight after expiry, and <code>option_expiry_settlement</code> chooses between settling at last traded price (keeping ITM value) and expiring every option worthless.</li></ul><p>Broker-specific RMS checks, queue priority, slippage, partial fills, outages, and exchange microstructure can differ from Analyzer results.</p><h3 id="default-sandbox-configuration" tabindex="-1">Default Sandbox Configuration <a class="header-anchor" href="#default-sandbox-configuration" aria-label="Permalink to &quot;Default Sandbox Configuration&quot;">​</a></h3><p>Open <code>/sandbox</code> to inspect and update settings. Fresh sandbox databases use:</p><table tabindex="0"><thead><tr><th>Setting</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td>Starting capital</td><td style="text-align:right;">INR 10,000,000</td></tr><tr><td>Automatic fund reset</td><td style="text-align:right;">Never (disabled)</td></tr><tr><td>Reset time when enabled</td><td style="text-align:right;">00:00 IST</td></tr><tr><td>Pending-order check interval</td><td style="text-align:right;">5 seconds</td></tr><tr><td>MTM update interval</td><td style="text-align:right;">5 seconds</td></tr><tr><td>NSE/BSE/NFO/BFO MIS square-off</td><td style="text-align:right;">15:15 IST</td></tr><tr><td>CDS/BCD MIS square-off</td><td style="text-align:right;">16:45 IST</td></tr><tr><td>MCX MIS square-off</td><td style="text-align:right;">23:30 IST</td></tr><tr><td>NCDEX MIS square-off</td><td style="text-align:right;">17:00 IST</td></tr><tr><td>Equity MIS leverage</td><td style="text-align:right;">5x</td></tr><tr><td>Equity CNC leverage</td><td style="text-align:right;">1x</td></tr><tr><td>Futures leverage</td><td style="text-align:right;">10x</td></tr><tr><td>Option buy leverage</td><td style="text-align:right;">1x</td></tr><tr><td>Option sell leverage</td><td style="text-align:right;">1x</td></tr><tr><td>Expiry settlement timing</td><td style="text-align:right;"><code>expiry_day_close</code></td></tr><tr><td>Option expiry settlement price</td><td style="text-align:right;"><code>ltp</code></td></tr><tr><td>OCO GTT margin mode</td><td style="text-align:right;"><code>max</code> (block only the larger leg)</td></tr><tr><td>GTT claim timeout</td><td style="text-align:right;">60 seconds</td></tr></tbody></table><p>These values configure the local simulator and can be changed. They are not promises about the active broker&#39;s live margin or square-off policy.</p><h3 id="validation-workflow" tabindex="-1">Validation Workflow <a class="header-anchor" href="#validation-workflow" aria-label="Permalink to &quot;Validation Workflow&quot;">​</a></h3><ol><li>Confirm <code>/api/v1/analyzer</code> reports <code>analyze_mode: true</code>.</li><li>Place one MARKET order and verify order book, trade book, position book, and funds.</li><li>Place a LIMIT or stop order away from the market and verify pending execution.</li><li>Exercise modify, cancel, smart, basket, and split flows used by the strategy.</li><li>Verify square-off and reset configuration instead of assuming defaults.</li><li>Review sandbox P&amp;L, order events, and errors.</li><li>Before live use, reduce quantity, verify mode again, and monitor the broker terminal.</li></ol><h3 id="reset-behavior" tabindex="-1">Reset Behavior <a class="header-anchor" href="#reset-behavior" aria-label="Permalink to &quot;Reset Behavior&quot;">​</a></h3><p>The Sandbox page provides manual reset controls and optional scheduled fund resets. A reset affects simulated state only. The default <code>reset_day</code> is <code>Never</code>, so the system does not perform a weekly reset unless an operator enables one.</p>`,22)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
